WITH cleaned AS (SELECT *, GREATEST(unit_price, quantity) greatest_unit_price_quantity FROM order_items WHERE order_id = 8), deduped AS (SELECT id, order_id, quantity, unit_price, greatest_unit_price_quantity FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY unit_price DESC, id) AS rank_in_group FROM cleaned) ranked WHERE rank_in_group = 1), with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY quantity DESC, id) seq_no, CORR(quantity, unit_price) OVER (PARTITION BY order_id) corr_quantity_unit_price FROM deduped WHERE greatest_unit_price_quantity > 26), with_dims AS (SELECT s.*, d.order_date, d.amount FROM with_windows s LEFT JOIN orders d ON s.order_id = d.id), with_windows_order_items AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY order_date, id) seq_no_2, CORR(quantity, unit_price) OVER (PARTITION BY order_id) corr_quantity_unit_price_2 FROM with_dims), grouped AS (SELECT CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, APPROX_PERCENTILE(seq_no, 0.95) AS seq_no_p95, APPROX_PERCENTILE(seq_no_2, ARRAY(0.25, 0.5, 0.75)) AS seq_no_2_quartiles FROM with_windows_order_items GROUP BY CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END HAVING seq_no_p95 > 0) SELECT quantity_tier, seq_no_p95, seq_no_2_quartiles FROM grouped ORDER BY quantity_tier DESC NULLS LAST
